def choose_move(observation):
    # Defensive defaults
    x = observation.get("player_x", 0)
    y = observation.get("player_y", 0)
    grid = observation.get("grid", [])
    width = observation.get("width", 0)
    height = observation.get("height", 0)

    # Helper to safely access grid cell with bounds checks
    def cell(nx, ny):
        if nx < 0 or ny < 0 or nx >= width or ny >= height:
            return None
        if not grid or ny >= len(grid) or nx >= len(grid[ny]):
            return None
        return grid[ny][nx]

    # Simple robust policy:
    # 1) If there is a nearby resource ('R') within 1 step, move toward it.
    # 2) Else if there is a nearby enemy ('E') within 2 steps, move away from it.
    # 3) Else stay or explore empty space.

    # Scan 3x3 around current position for resource
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if cell(nx, ny) == 'R':
                return [dx, dy]

    # Look for nearest enemy within 2 steps
    best_enemy = None
    min_dist = 999
    for dy in (-2, -1, 0, 1, 2):
        for dx in (-2, -1, 0, 1, 2):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if cell(nx, ny) == 'E':
                dist = abs(dx) + abs(dy)
                if dist < min_dist:
                    min_dist = dist
                    best_enemy = (dx, dy)
    if best_enemy:
        # Move away from enemy
        ex, ey = best_enemy
        move_dx = -ex
        move_dy = -ey
        # Clamp to [-1,1]
        if move_dx < -1: move_dx = -1
        if move_dx > 1: move_dx = 1
        if move_dy < -1: move_dy = -1
        if move_dy > 1: move_dy = 1
        return [move_dx, move_dy]

    # Fallback: try to move toward any empty cell in 1-step neighborhood
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if cell(nx, ny) in (None, ' '):
                return [dx, dy]

    # If all else fails, stay
    return [0, 0]

